#include "Processor.h"
#include "OscAdvanced.h"
#include <cstring>
using namespace juce;
namespace noctrl {
void LiveBinding::apply(Settings& settings,float value)const{if(offset<0)return;char* at=reinterpret_cast<char*>(&settings)+offset;if(kind==1)*reinterpret_cast<int*>(at)=roundToInt(value);else *reinterpret_cast<float*>(at)=kind==2?mixDbGain(value):kind==3?value/360:value;}
LiveBinding liveBinding(const String& target){Settings s;std::map<String,LiveBinding> map;auto f=[&](String id,float& ref,bool voice=true,int kind=0){map[id]={(int)(reinterpret_cast<char*>(&ref)-reinterpret_cast<char*>(&s)),kind,voice};};auto integer=[&](String id,int& ref,bool voice=true){map[id]={(int)(reinterpret_cast<char*>(&ref)-reinterpret_cast<char*>(&s)),1,voice};};for(int i=0;i<3;++i){auto id="osc"+String(i+1);auto& o=s.osc[i];f(id+"pos",o.position);f(id+"level",o.level);f(id+"detune",o.detune);integer(id+"oct",o.octave);integer(id+"voices",o.unison);f(id+"semi",o.semi);f(id+"fine",o.fine);f(id+"phase",o.initial,true,3);f(id+"random",o.random,false);f(id+"pan",o.pan);f(id+"blend",o.blend);for(auto& spec:oscAdvancedSpecs())if(spec.choices.isEmpty())f(id+spec.id,o.*spec.field);for(int k=0;k<16;++k)f(id+"spectralPoint"+String(k+1),o.spectralCurve[k]);for(int w=0;w<2;++w){f(id+"warp"+String(w+1)+"var",o.warpVar[w]);for(int k=0;k<16;++k)f(id+"warp"+String(w+1)+"remap"+String(k+1),o.remap[w][k]);}for(int w=0;w<2;++w)f(id+"warp"+String(w+1),o.warpAmount[w]);}
 for(int e=0;e<4;++e){auto id="env"+String(e+1);f(id+"a",s.envelopes[e].attack);f(id+"d",s.envelopes[e].decay);f(id+"s",s.envelopes[e].sustain);f(id+"r",s.envelopes[e].release);f(id+"hold",s.hold[e]);}for(int i=0;i<8;++i){auto id="lfo"+String(i+1);f(id+"rate",s.lfoRate[i]);f(id+"phase",s.lfoOffset[i]);for(int k=0;k<16;++k)f(id+"point"+String(k+1),s.lfoPoints[i][k]);f("macro"+String(i+1),s.macro[i],false);}for(int i=0;i<2;++i){auto id="filter"+String(i+1);f(id+"cut",s.cutoff[i]);f(id+"res",s.resonance[i]);f(id+"drive",s.filterDrive[i]);f(id+"wet",s.filterWet[i]);f(id+"pan",s.filterPan[i]);}
 f("sub",s.sub);f("noise",s.noise);f("subPan",s.subPan);f("subOct",s.subOct);f("subCoarse",s.subCoarse);f("subPhase",s.subInitial,false,3);f("noisePan",s.noisePan);f("noisePitch",s.noisePitch);f("filterEnv",s.filterEnv);f("glide",s.glide,false);integer("polyphony",s.polyphony,false);f("output",s.output,false);f("drive",s.drive,false);f("chorus",s.chorus,false);f("delay",s.delay,false);f("feedback",s.feedback,false);f("reverb",s.reverb,false);
 for(int i=0;i<7;++i){auto key=i<5?mixSources[i]:"Filter"+String(i-4);if(i<5)f("mix"+key+"Balance",s.mix.balance[i]);for(int bus=0;bus<2;++bus)f("mix"+key+"Bus"+String(bus+1),s.mix.send[i][bus]);}const String channels[]={"Filter1","Filter2","Bus1","Bus2","Main","Direct"};for(int i=0;i<6;++i){f("mix"+channels[i]+"Db",s.mix.gain[i],i<2,2);if(i>=2)f("mix"+channels[i]+"Pan",s.mix.pan[i-2],false);}auto found=map.find(target);return found==map.end()?LiveBinding{}:found->second;
}
ValueTree LiveModRouting::save()const{ValueTree tree("LiveModRouting");for(auto& link:links){ValueTree value("Link");value.setProperty("source",link.source,nullptr);value.setProperty("target",link.target,nullptr);value.setProperty("base",link.base,nullptr);value.setProperty("start",link.start,nullptr);value.setProperty("end",link.end,nullptr);tree.addChild(value,-1,nullptr);}return tree;}
void LiveModRouting::compile(){groups.clear();for(auto& link:links){auto found=std::find_if(groups.begin(),groups.end(),[&](auto& group){return group.index==link.index;});if(found==groups.end()){LiveModGroup group;group.index=link.index;group.target=link.target;group.parameter=link.parameter;group.binding=liveBinding(link.target);group.macro=link.target.startsWith("macro");groups.push_back(std::move(group));found=groups.end()-1;}found->links.push_back(link);}}
void SynthProcessor::publishLiveMods(std::shared_ptr<LiveModRouting> next){next->compile();auto previous=std::atomic_exchange(&liveModRouting,std::shared_ptr<const LiveModRouting>(next));if(previous)retiredLiveRouting.push_back(std::move(previous));retiredLiveRouting.erase(std::remove_if(retiredLiveRouting.begin(),retiredLiveRouting.end(),[](auto& item){return item.use_count()==1;}),retiredLiveRouting.end());}
bool SynthProcessor::assignLiveMod(int source,const String& target){auto* parameter=state.getParameter(target);if(source<0||source>=liveSourceCount||!parameter||dynamic_cast<AudioParameterBool*>(parameter)||dynamic_cast<AudioParameterChoice*>(parameter))return false;auto next=std::make_shared<LiveModRouting>(*liveMods());if(next->find(source,target))return true;if(next->links.size()>=256)return false;float base=parameter->getValue(),start=source<3?base:jmax(0.f,base-.125f),end=source<3?(base>.75f?jmax(0.f,base-.25f):jmin(1.f,base+.25f)):jmin(1.f,base+.125f);next->links.push_back({source,parameter->getParameterIndex(),target,base,start,end,parameter});publishLiveMods(next);return true;}
void SynthProcessor::setLiveModRange(int source,const String& target,float start,float end){if(!std::isfinite(start)||!std::isfinite(end))return;auto next=std::make_shared<LiveModRouting>(*liveMods());for(auto& link:next->links)if(link.source==source&&link.target==target){link.start=jlimit(0.f,1.f,start);link.end=jlimit(0.f,1.f,end);}publishLiveMods(next);}
void SynthProcessor::removeLiveMod(int source,const String& target){auto next=std::make_shared<LiveModRouting>(*liveMods());next->links.erase(std::remove_if(next->links.begin(),next->links.end(),[&](auto& link){return link.target==target&&(source<0||link.source==source);}),next->links.end());publishLiveMods(next);}
void SynthProcessor::restoreLiveMods(const ValueTree& tree){auto next=std::make_shared<LiveModRouting>();for(auto child:tree){int source=(int)child.getProperty("source",-1);String target=child["target"];auto* parameter=state.getParameter(target);float base=(float)child.getProperty("base",0),start=(float)child.getProperty("start",0),end=(float)child.getProperty("end",1);if(source<0||source>=liveSourceCount||!parameter||dynamic_cast<AudioParameterBool*>(parameter)||dynamic_cast<AudioParameterChoice*>(parameter)||!std::isfinite(base)||!std::isfinite(start)||!std::isfinite(end)||next->find(source,target)||next->links.size()>=256)continue;next->links.push_back({source,parameter->getParameterIndex(),target,jlimit(0.f,1.f,base),jlimit(0.f,1.f,start),jlimit(0.f,1.f,end),parameter});}publishLiveMods(next);selectedLiveSource.store(-1);}
void SynthProcessor::refreshLiveGlobals(){if(!blockLiveRouting)return;std::array<float,liveSourceCount> sources;for(int i=0;i<liveSourceCount;++i)sources[i]=liveSources[i].load(std::memory_order_relaxed);for(auto& group:blockLiveRouting->groups)if(!group.binding.voice){float value=group.value(liveModBaseValues[(size_t)group.index],sources);effectiveParameters[(size_t)group.index]=value;group.binding.apply(settings,value);}}
}
